<script>$('#traffic-provider').on('change',function(){var p=this.value,$text=$('#provider-check-text'),$wrap=$('#provider-token-wrap');$wrap.hide();if(!p){$text.text('');return}$text.html('<i class="fa fa-spinner fa-spin"></i> Đang kiểm tra token...');fetch('/model/admin/traffic/provider-status?provider='+encodeURIComponent(p),{credentials:'same-origin'}).then(r=>r.json()).then(j=>{if(j.configured){$text.html('<span class="text-success">✓ Đã cấu hình token</span>');}else{$text.html('<span class="text-danger">✕ Chưa có token</span>');if(j.can_configure)$wrap.show();}}).catch(()=>{$text.text('Không kiểm tra được');});}).trigger('change');</script>
